insert into public.resources (type, slug, title, content) select type, slug, title, content from jsonb_to_recordset('[{"type":"course","slug":"understanding-climate-change-crashcourse-guide","title":"Understanding Climate Change: A CrashCourse Playlist Guide","content":{"slug":"understanding-climate-change-crashcourse-guide","title":"Understanding Climate Change: A CrashCourse Playlist Guide","intro":"Climate change is one of the most urgent challenges of our time. But where do you start? In this blog post, we’ll walk through the CrashCourse Climate & Energy playlist—13 concise, engaging videos that build from the very basics of what climate change is, all the way to the policies, technologies, and actions we need to address it. Bookmark this guide, follow along video by video, and by the end you’ll have a solid foundation in both the science and the solutions.","sections":[{"heading":"Further Reading & Resources","items":["IPCC Summary for Policymakers","NASA Global Climate Change Dashboard","Your local government’s climate action plan"]},{"heading":"Get Involved","items":["Join a local environmental group","Support legislation for clean energy","Reduce your own carbon footprint"]}],"conclusion":"This CrashCourse Climate & Energy series offers a comprehensive yet digestible journey through the science, technology, economics, and politics of climate change. By watching these videos and diving into the supplementary resources above, you’ll be well equipped to understand the challenges we face—and to play your part in crafting solutions. Let’s keep learning, keep sharing, and keep pushing for a sustainable future!","createdAt":"2025-07-05T12:00:00.000Z","updatedAt":"2025-07-05T12:00:00.000Z","contents":[{"order":1,"title":"Crash Course Climate & Energy Preview","description":"A quick teaser of what’s to come—definitions, big questions, and why this series matters now.","takeaways":["Lay out the scope of the series","Provide a roadmap for upcoming topics"],"youtubeUrl":"https://youtube.com/embed/dhFlDkES6Ws?si=sG3itut9DUKgthv0"},{"order":2,"title":"What is Climate Change? (Climate & Energy #1)","description":"An introduction to Earth’s climate system—how it works, the difference between weather and climate, and why humans are altering it.","takeaways":["Carbon cycle basics","Greenhouse effect fundamentals","How small changes can have huge impacts"],"youtubeUrl":"https://youtube.com/embed/9PFhrpyWV-w?si=MVmZBVRzZOvcMF4C"},{"order":3,"title":"Why Do We Release So Much Gas? (Climate & Energy #2)","description":"A look at where greenhouse gases come from—fossil fuels, deforestation, agriculture, and more.","takeaways":["Historical CO₂ rise","Anthropogenic vs. natural emissions","Biggest culprits in daily life"],"youtubeUrl":"https://youtube.com/embed/Q26Z4JWVZvk?si=IIwQ_G9D_BoI9AAR"},{"order":4,"title":"Can We Make Electricity Without Fossil Fuels? (Climate & Energy #3)","description":"Explores renewable electricity sources—solar, wind, hydro, geothermal, and the challenges of scale.","takeaways":["Capacity factors","Intermittency","Why a diverse mix of renewables is crucial"],"youtubeUrl":"https://youtube.com/embed/pT7vRUGeEtA?si=M-KaQ-mBh3fyUd_Q"},{"order":5,"title":"How Can We Store Renewable Energy? (Climate & Energy #4)","description":"Delves into energy storage technologies like batteries, pumped hydro, and emerging solutions like flow batteries and supercapacitors.","takeaways":["The “duck curve”","Round‑trip efficiency","The race for next‑generation storage"],"youtubeUrl":"https://youtube.com/embed/rDkaZWirNME?si=4Pf74eVmSNZwOGqs"},{"order":6,"title":"Can We Keep Warm and Stay Cool Without Fossil Fuels? (Climate & Energy #5)","description":"Heating and cooling account for a huge chunk of energy use—this episode covers heat pumps, passive design, and efficiency upgrades.","takeaways":["Coefficient of Performance (COP)","District heating","Building retrofits"],"youtubeUrl":"https://youtube.com/embed/3yH5TuLYRcs?si=YjXBzSbDw5QOjLmX"},{"order":7,"title":"Can We Gas Up… Without Gas? (Climate & Energy #6)","description":"Transportation’s energy dilemma—electric vehicles, biofuels, hydrogen, and the infrastructure needed to make the switch.","takeaways":["Well‑to‑wheel emissions","Charging networks","Lifecycle analysis"],"youtubeUrl":"https://youtube.com/embed/1-YtC3nwWwU?si=Tb6HgLxJSAwbHCvP"},{"order":8,"title":"Can We Capture Greenhouse Gases? (Climate & Energy #7)","description":"Carbon capture and storage (CCS) and direct air capture (DAC)—how they work, costs, and the controversy around “negative emissions.”","takeaways":["Absorption vs. adsorption","Geological sequestration","Role of nature‑based solutions"],"youtubeUrl":"https://youtube.com/embed/bjIXPPlg1TQ?si=a5terKRPn_LnMZlu"},{"order":9,"title":"How Will Climate Change Continue to Affect Us? (Climate & Energy #8)","description":"Projections of sea‑level rise, extreme weather, agriculture impacts, and human health.","takeaways":["Climate models","Vulnerability assessments","Concept of “climate resilience”"],"youtubeUrl":"https://youtube.com/embed/eVUuwHGLIYo?si=-_b9LWFN0dY3lC7q"},{"order":10,"title":"Are Natural Disasters Actually Natural? (Climate Justice) (Climate & Energy #9)","description":"The human and societal dimensions of climate impacts—why some communities suffer more, and how equity fits into adaptation and mitigation.","takeaways":["Climate justice principles","Loss and damage","Ethics of responsibility"],"youtubeUrl":"https://youtube.com/embed/7ODrQW0vSmA?si=666PfZvHGotv_8Ww"},{"order":11,"title":"International Climate Agreements (Climate & Energy #10)","description":"From Kyoto to the Paris Agreement—how countries negotiate targets, finance, and technology transfer.","takeaways":["Nationally Determined Contributions (NDCs)","Global stocktake","Role of non‑state actors"],"youtubeUrl":"https://youtube.com/embed/Z5YvjG4lTpQ?si=XreeEX1uG4Zf76y7"},{"order":12,"title":"The Hidden Price of Climate Change (Climate & Energy #11)","description":"Economic impacts—costs of disasters, insurance, stranded assets, and carbon pricing mechanisms.","takeaways":["Social cost of carbon","Cap‑and‑trade vs. carbon tax","Economics of inaction"],"youtubeUrl":"https://youtube.com/embed/ML70W4O6F4E?si=uqUYbDKuidULafW3"},{"order":13,"title":"How Can We Respond to Climate Change? (Climate & Energy #12)","description":"A call to action—individual choices, technological pathways, policy levers, and the importance of collective effort.","takeaways":["Mitigation vs. adaptation","Climate activism","How you can get involved"],"youtubeUrl":"https://youtube.com/embed/3p51wKUuwOU?si=tdRBWD1iVzNB27Ej"}],"type":"course","duration":"2 hours","level":"Beginner","numberOfLesson":"13","authors":["CrashCourse"]}},{"type":"guide","slug":"socio-cultural-sustainability-university-guide","title":"Recognising & Sustaining the Socio‑Cultural Pillar: A Guide for University Students","content":{"slug":"socio-cultural-sustainability-university-guide","title":"Recognising & Sustaining the Socio‑Cultural Pillar: A Guide for University Students","description":"An in‑depth walkthrough for university students to understand, recognise, and strengthen the socio‑cultural pillar of sustainability in campus life—with practical examples, reflection prompts, and action steps.","presentationLink":"https://www.canva.com/design/DAGt2SkrC8w/0y4XMI06a34jv2SVYzGh-w/view","contents":[],"type":"guide","createdAt":"2025-07-05T12:00:00.000Z","updatedAt":"2025-07-25T15:00:00.000Z","authors":["Rozil Nguyen"]}},{"type":"guide","slug":"zero-waste-swaps-uni-guide","title":"Zero-Waste Swaps for Uni Life: 3 Levels of Sustainable Habits","content":{"slug":"zero-waste-swaps-uni-guide","title":"Zero-Waste Swaps for Uni Life: 3 Levels of Sustainable Habits","description":"A practical and visual guide for university students to adopt sustainable living through zero-waste swaps. Learn how to save money and reduce your carbon footprint through three tiers of eco-friendly lifestyle changes—from quick wins to long-term upgrades.","presentationLink":"https://www.canva.com/design/DAGs1-DXhPw/BSP0eggNmdkaYRNYhP8wZA/view","contents":[],"type":"guide","createdAt":"2025-07-05T12:00:00.000Z","updatedAt":"2025-07-25T15:00:00.000Z","authors":["Rozil Nguyen"]}},{"type":"guide","slug":"myth-buster-sustainability-not-synonym-green","title":"Myth Buster: Sustainability Is Not a Synonym for “Green”","content":{"slug":"myth-buster-sustainability-not-synonym-green","title":"Myth Buster: Sustainability Is Not a Synonym for “Green”","description":"A visual blog guide for university students that uses the four‑legged sustainability stool metaphor to unpack the environmental, economic, social‑cultural, and political pillars—and shows how to weave them into campus projects and teaching.","presentationLink":"https://www.canva.com/design/DAGtPdVYvtI/SqvaU8be10urBw1UWrQIrg/view","contents":[],"type":"guide","createdAt":"2025-07-27T23:46:40.000Z","updatedAt":"2025-07-27T23:46:40.000Z","authors":["Rozil Nguyen"]}},{"type":"guide","slug":"economic-sustainability-university-guide","title":"Economic Sustainability: A Student Guide (Clean & Actionable)","content":{"slug":"economic-sustainability-university-guide","title":"Economic Sustainability: A Student Guide (Clean & Actionable)","description":"A concise, practical guide for university students to understand economic sustainability: what it is, how to spot it on campus, and simple daily & community actions to strengthen financial resilience, local value circulation, and career-ready skills.","presentationLink":"https://www.canva.com/design/DAGv6CilIA0/TghStC0Qj88ZH_AM3FxJfA/view","contents":[],"type":"guide","createdAt":"2025-07-05T12:00:00.000Z","updatedAt":"2025-07-25T15:00:00.000Z","authors":["Rozil Nguyen"]}},{"type":"video","slug":"climate-change-averting-catastrophe","title":"Climate change - Averting catastrophe","content":{"title":"Climate change - Averting catastrophe","description":"In the last 30 years, CO2 emissions have increased by 60 percent worldwide. The most pressing problem facing our civilization is global warming. What solutions could there be? This documentary accompanies activists in their efforts to combat climate change.","videoLink":"https://www.youtube.com/embed/pEt6-jA2UE4?si=pE-3e6_fgx_-sPtF","type":"video","duration":"1:25:56","uploadDate":"14 Jul 2023","authors":["DW Documentary"]}},{"type":"video","slug":"we-will-fix-climate-change","title":"We WILL Fix Climate Change!","content":{"title":"We WILL Fix Climate Change!","description":"Our home is burning. Rapid climate change is destabilizing our world. It seems our emissions will not fall quickly enough to avoid runaway warming and we may soon hit tipping points that will lead to the collapse of ecosystems and our civilization. While scientists, activists and much of the younger generation urge action, it appears most politicians are not committed to do anything meaningful while the fossil fuel industry still works actively against change. It seems humanity can’t overcome its greed and obsession with short term profit and personal gain to save itself. And so for many the future looks grim and hopeless. Young people feel particularly anxious and depressed. Instead of looking ahead to a lifetime of opportunity they wonder if they will even have a future or if they should bring kids into this world. It’s an age of doom and hopelessness and giving up seems the only sensible thing to do. But that’s not true. You are not doomed. Humanity is not doomed.","authors":["Kurzgesagt – In a Nutshell"],"type":"video","duration":"1:25:56","uploadDate":"14 Jul 2023","videoLink":"https://www.youtube.com/embed/LxgMdjyw8uw?si=pnJgbzM754XIkyKw"}},{"type":"research","slug":"climate-impact-of-increasing-atmospheric-carbon-dioxide","title":"Climate Impact of Increasing Atmospheric Carbon Dioxide","content":{"slug":"climate-impact-of-increasing-atmospheric-carbon-dioxide","title":"Climate Impact of Increasing Atmospheric Carbon Dioxide","abstract":"The global temperature rose by 0.2°C between the middle 1960''s and 1980, yielding a warming of 0.4°C in the past century. This temperature increase is consistent with the calculated greenhouse effect due to measured increases of atmospheric carbon dioxide. Variations of volcanic aerosols and possibly solar luminosity appear to be primary causes of observed fluctuations about the mean trend of increasing temperature. It is shown that the anthropogenic carbon dioxide warming should emerge from the noise level of natural climate variability by the end of the century, and there is a high probability of warming in the 1980''s. Potential effects on climate in the 21st century include the creation of drought-prone regions in North America and central Asia as part of a shifting of climatic zones, erosion of the West Antarctic ice sheet with a consequent worldwide rise in sea level, and opening of the fabled Northwest Passage.","researchLink":"https://doi.org/10.1126/science.213.4511.957","authors":["J. Hansen et al."],"type":"research","year":"1981","keywords":["Greenhouse effect","Radiative forcing","CO₂ doubling","Climate modeling","Temperature projection"]}},{"type":"research","slug":"greenhouse‐gas-emission-targets-for-limiting-global-warming-to-2-degree","title":"Greenhouse‐gas emission targets for limiting global warming to 2 °C.","content":{"slug":"greenhouse‐gas-emission-targets-for-limiting-global-warming-to-2-degree","title":"Greenhouse‐gas emission targets for limiting global warming to 2 °C.","abstract":"More than 100 countries have adopted a global warming limit of 2 °C or below (relative to pre-industrial levels) as a guiding principle for mitigation efforts to reduce climate change risks, impacts and damages1,2. However, the greenhouse gas (GHG) emissions corresponding to a specified maximum warming are poorly known owing to uncertainties in the carbon cycle and the climate response. Here we provide a comprehensive probabilistic analysis aimed at quantifying GHG emission budgets for the 2000–50 period that would limit warming throughout the twenty-first century to below 2 °C, based on a combination of published distributions of climate system properties and observational constraints. We show that, for the chosen class of emission scenarios, both cumulative emissions up to 2050 and emission levels in 2050 are robust indicators of the probability that twenty-first century warming will not exceed 2 °C relative to pre-industrial temperatures. Limiting cumulative CO2 emissions over 2000–50 to 1,000 Gt CO2 yields a 25% probability of warming exceeding 2 °C—and a limit of 1,440 Gt CO2 yields a 50% probability—given a representative estimate of the distribution of climate system properties. As known 2000–06 CO2 emissions3 were ∼234 Gt CO2, less than half the proven economically recoverable oil, gas and coal reserves4,5,6 can still be emitted up to 2050 to achieve such a goal. Recent G8 Communiqués7 envisage halved global GHG emissions by 2050, for which we estimate a 12–45% probability of exceeding 2 °C—assuming 1990 as emission base year and a range of published climate sensitivity distributions. Emissions levels in 2020 are a less robust indicator, but for the scenarios considered, the probability of exceeding 2 °C rises to 53–87% if global GHG emissions are still more than 25% above 2000 levels in 2020.","researchLink":"https://doi.org/10.1038/nature08017","authors":["Meinshausen","M., Meinshausen","N., Hare","W. et al."],"type":"research","year":"2009","keywords":["Emission budgets","2 °C target","Cumulative CO₂","Probability thresholds","Integrated assessment models"]}},{"type":"research","slug":"tipping-elements-in-the-earth''s-climate-system","title":"Tipping elements in the Earth''s climate system","content":{"slug":"tipping-elements-in-the-earth''s-climate-system","title":"Tipping elements in the Earth''s climate system","abstract":"The term “tipping point” commonly refers to a critical threshold at which a tiny perturbation can qualitatively alter the state or development of a system. Here we introduce the term “tipping element” to describe large-scale components of the Earth system that may pass a tipping point. We critically evaluate potential policy-relevant tipping elements in the climate system under anthropogenic forcing, drawing on the pertinent literature and a recent international workshop to compile a short list, and we assess where their tipping points lie. An expert elicitation is used to help rank their sensitivity to global warming and the uncertainty about the underlying physical mechanisms. Then we explain how, in principle, early warning systems could be established to detect the proximity of some tipping points.","researchLink":"https://doi.org/10.1073/pnas.0705414105","authors":["T.M. Lenton","H. Held","E. Kriegler","J.W. Hall","W. Lucht","S. Rahmstorf","H.J. Schellnhuber"],"type":"research","year":"2008","keywords":["Tipping points","Abrupt change","Earth system feedbacks","Irreversibility","Critical thresholds"]}},{"type":"art","slug":"silent-drowning","title":"Silent Drowning","content":{"title":"Silent Drowning","artist":"Jessica Mei Phillips","medium":"Watercolour, gouache, and white gel pen on watercolour paper","year":"2025","dimensions":"16cm x 16cm","description":"An otter struggles to swim through thick, blackened water after an oil spill. Once playful and free, the creature now battles for breath, its fur heavy with toxic oil. This artwork not only advocates for the protection of our oceans, but also serves as a reminder that our actions — from the energy we use to the waste we create — have real and lasting consequences for the environment and its inhabitants.","image":"/painting/otter.jpeg","technique":"Layered washes of watercolour were used to build the depth of the polluted water, while gouache added rich opacity to the oil slick. A white gel pen was applied for fine highlights on the otter’s whiskers and the glisten of the water. The combination of mediums creates both softness and stark contrast, mirroring the clash between nature and human impact.","inspiration":"Inspired by images of oil spill disasters and their toll on marine life, this piece aims to spark empat","artistBio":"Jessica Mei Phillips is a drawing-focused artist who loves portraiture—capturing quiet expressions and personality through line and mark. She lives with a cat who’s often her studio companion.","type":"art"}}]'::jsonb) as row(type text, slug text, title text, content jsonb) on conflict (type, slug) do update set title=excluded.title, content=excluded.content;
insert into public.recommendations (title, description, category, impact, impact_value, difficulty, trees_earned) select title, description, category, impact, impact_value, difficulty, trees_earned from jsonb_to_recordset('[{"title":"Metro to Campus","description":"Use the Sydney Metro instead of driving to Macquarie University.","category":"transportation","impact":"10.2 kg CO₂ saved","impact_value":10.2,"difficulty":"Easy","trees_earned":1},{"title":"Bike to Class","description":"Cycle to campus and park near MUSE or 10 Wally''s Walk.","category":"transportation","impact":"14.5 kg CO₂ saved","impact_value":14.5,"difficulty":"Medium","trees_earned":2},{"title":"Carpool with Classmates","description":"Organize rides with friends to reduce single-passenger trips.","category":"transportation","impact":"12.7 kg CO₂ saved","impact_value":12.7,"difficulty":"Medium","trees_earned":2},{"title":"Walk Between Buildings","description":"Skip the shuttle , walk to your next class for health and the planet.","category":"transportation","impact":"4.2 kg CO₂ saved","impact_value":4.2,"difficulty":"Easy","trees_earned":1},{"title":"Tap Opal Off-Peak","description":"Travel off-peak using your Opal card to reduce congestion and emissions.","category":"transportation","impact":"6.3 kg CO₂ saved","impact_value":6.3,"difficulty":"Easy","trees_earned":1},{"title":"Veggie UBar Day","description":"Choose the plant-based burger at UBar once this week.","category":"fooddiet","impact":"5.6 kg CO₂ saved","impact_value":5.6,"difficulty":"Easy","trees_earned":1},{"title":"Reusable Coffee Cup","description":"Bring your own mug to Courtyard Café to cut waste and get discounts.","category":"fooddiet","impact":"1.9 kg CO₂ saved","impact_value":1.9,"difficulty":"Easy","trees_earned":1},{"title":"Meat-Free Monday","description":"Go vegetarian every Monday for one month.","category":"fooddiet","impact":"9.8 kg CO₂ saved","impact_value":9.8,"difficulty":"Medium","trees_earned":2},{"title":"Zero Waste Meal Plan","description":"Use all groceries before expiry this week.","category":"fooddiet","impact":"4.7 kg CO₂ saved","impact_value":4.7,"difficulty":"Medium","trees_earned":1},{"title":"Buy Local Challenge","description":"Get fresh produce from local markets or vendors near campus.","category":"fooddiet","impact":"6.1 kg CO₂ saved","impact_value":6.1,"difficulty":"Medium","trees_earned":1},{"title":"Dorm Device Unplug","description":"Unplug laptop, chargers, and lamps in your dorm when not in use.","category":"homeenergy","impact":"5.4 kg CO₂ saved","impact_value":5.4,"difficulty":"Easy","trees_earned":1},{"title":"Power-Saving Mode","description":"Enable eco mode on your laptop and phone for a full week.","category":"homeenergy","impact":"3.3 kg CO₂ saved","impact_value":3.3,"difficulty":"Easy","trees_earned":1},{"title":"Charge at the Library","description":"Use the solar-powered library to charge devices instead of your dorm.","category":"homeenergy","impact":"2.7 kg CO₂ saved","impact_value":2.7,"difficulty":"Easy","trees_earned":1},{"title":"Lights Out Habit","description":"Turn off lights in shared dorm areas when leaving.","category":"homeenergy","impact":"4.8 kg CO₂ saved","impact_value":4.8,"difficulty":"Easy","trees_earned":1},{"title":"Natural Light Days","description":"Use natural daylight for study instead of artificial lights.","category":"homeenergy","impact":"3.6 kg CO₂ saved","impact_value":3.6,"difficulty":"Easy","trees_earned":1},{"title":"Textbook Swap","description":"Buy or trade secondhand textbooks from other students.","category":"shopping","impact":"7.5 kg CO₂ saved","impact_value":7.5,"difficulty":"Easy","trees_earned":1},{"title":"Reuse Market Visit","description":"Pick up or donate items at the campus reuse market.","category":"shopping","impact":"6.9 kg CO₂ saved","impact_value":6.9,"difficulty":"Easy","trees_earned":1},{"title":"No-Buy Week","description":"Avoid all non-essential purchases for one week.","category":"shopping","impact":"12.2 kg CO₂ saved","impact_value":12.2,"difficulty":"Hard","trees_earned":3},{"title":"Library Loan First","description":"Borrow electronics or materials from the library before buying.","category":"shopping","impact":"5.2 kg CO₂ saved","impact_value":5.2,"difficulty":"Easy","trees_earned":1},{"title":"Bag It Better","description":"Use a reusable bag at Macquarie Centre for every purchase this week.","category":"shopping","impact":"2.4 kg CO₂ saved","impact_value":2.4,"difficulty":"Easy","trees_earned":1},{"title":"Download Lectures","description":"Watch lectures offline instead of streaming them repeatedly.","category":"digitalusage","impact":"3.1 kg CO₂ saved","impact_value":3.1,"difficulty":"Medium","trees_earned":1},{"title":"Tab Management Master","description":"Keep fewer browser tabs open while studying.","category":"digitalusage","impact":"1.7 kg CO₂ saved","impact_value":1.7,"difficulty":"Easy","trees_earned":1},{"title":"Low-Bandwidth Zoom","description":"Disable HD video and backgrounds in Zoom for all your meetings this week.","category":"digitalusage","impact":"2.9 kg CO₂ saved","impact_value":2.9,"difficulty":"Medium","trees_earned":1},{"title":"Dark Mode Days","description":"Use dark mode on all your devices for the entire week.","category":"digitalusage","impact":"1.6 kg CO₂ saved","impact_value":1.6,"difficulty":"Easy","trees_earned":1},{"title":"Email Efficiency","description":"Send fewer, consolidated emails to reduce cloud activity.","category":"digitalusage","impact":"2.2 kg CO₂ saved","impact_value":2.2,"difficulty":"Easy","trees_earned":1}]'::jsonb) as row(title text, description text, category text, impact text, impact_value double precision, difficulty text, trees_earned integer) on conflict (title) do update set description=excluded.description, category=excluded.category, impact=excluded.impact, impact_value=excluded.impact_value, difficulty=excluded.difficulty, trees_earned=excluded.trees_earned;
